#include <iostream>
#include <vector>
#include <string>
using namespace std;

using int64 = long long;

struct Matrix {
    int size;
    vector<vector<int64>> a;

    Matrix(int n, bool identity = false) : size(n), a(n, vector<int64>(n, 0)) {
        if (identity) {
            for (int i = 0; i < n; ++i) a[i][i] = 1;
        }
    }
};

Matrix operator*(const Matrix& x, const Matrix& y) {
    Matrix result(x.size);
    for (int i = 0; i < x.size; ++i) {
        for (int k = 0; k < x.size; ++k) {
            if (x.a[i][k] == 0) continue;
            for (int j = 0; j < x.size; ++j) {
                result.a[i][j] += x.a[i][k] * y.a[k][j];
            }
        }
    }
    return result;
}

Matrix matrixPower(Matrix base, int exponent) {
    Matrix result(base.size, true);
    while (exponent > 0) {
        if (exponent & 1) result = result * base;
        base = base * base;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    int m = static_cast<int>(s.size());

    vector<int> prefix(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = prefix[i - 1];
        while (j > 0 && s[i] != s[j]) j = prefix[j - 1];
        if (s[i] == s[j]) ++j;
        prefix[i] = j;
    }

    Matrix transition(m);

    for (int state = 0; state < m; ++state) {
        for (char bit : {'0', '1'}) {
            int next = state;
            while (next > 0 && s[next] != bit) {
                next = prefix[next - 1];
            }
            if (s[next] == bit) ++next;

            if (next < m) {
                ++transition.a[state][next];
            }
        }
    }

    Matrix powered = matrixPower(transition, n);

    int64 avoiding = 0;
    for (int i = 0; i < m; ++i) {
        avoiding += powered.a[i][i];
    }

    int64 total = 1LL << n;
    cout << total - avoiding << '\n';

    return 0;
}

