#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    int m = s.size();
    vector<int> pi(m);

    for (int i = 1; i < m; ++i) {
        int j = pi[i - 1];
        while (j > 0 && s[i] != s[j]) j = pi[j - 1];
        if (s[i] == s[j]) ++j;
        pi[i] = j;
    }

    vector<array<int, 2>> go(m);
    for (int state = 0; state < m; ++state) {
        for (int bit = 0; bit < 2; ++bit) {
            char c = char('0' + bit);
            int next = state;

            while (next > 0 && s[next] != c)
                next = pi[next - 1];
            if (s[next] == c) ++next;

            go[state][bit] = (next == m ? -1 : next);
        }
    }

    unsigned long long avoiding = 0;

    for (int start = 0; start < m; ++start) {
        vector<unsigned long long> dp(m), nextDp(m);
        dp[start] = 1;

        for (int i = 0; i < n; ++i) {
            fill(nextDp.begin(), nextDp.end(), 0);

            for (int state = 0; state < m; ++state) {
                for (int bit = 0; bit < 2; ++bit) {
                    int next = go[state][bit];
                    if (next != -1)
                        nextDp[next] += dp[state];
                }
            }

            dp.swap(nextDp);
        }

        avoiding += dp[start];
    }

    unsigned long long total = 1ULL << n;
    cout << total - avoiding << '\n';

    return 0;
}
